package com.afterglow.player;
import android.app.*;import android.content.*;import android.os.*;import java.util.*;import java.io.*;import java.util.zip.*;
public class UpgradeChecks extends Instrumentation {
 public void onCreate(Bundle b){super.onCreate(b);start();}void check(boolean ok,String label){if(!ok)throw new AssertionError(label);android.util.Log.i("AfterglowUpgrade","PASS "+label);}interface Condition{boolean ready();}void await(Condition c,int seconds)throws Exception{for(int n=0;n<seconds*10;n++){if(c.ready())return;Thread.sleep(100);}throw new AssertionError("Timed out waiting for state");}
 public void onStart(){Bundle result=new Bundle();PlaybackService s=null;ArrayList<Track> saved=null,next=null;int oldIndex=0;boolean oldRepeat=false;String key=null;MainActivity a=null;try{
  a=(MainActivity)startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));await(()->PlaybackService.instance!=null,10);s=PlaybackService.instance;final PlaybackService p=s;final MainActivity ui=a;saved=new ArrayList<>(s.queue);next=new ArrayList<>(s.upcoming);oldIndex=s.index;oldRepeat=s.repeat;key=s.searchKey;
  check(AudioCache.LIMIT==3221225472L,"3 GiB cache cap");check(!p.trackStatus(new Track("Unresolved","Artist","","query")).contains("Downloading"),"Empty title IDs never display downloading");runOnMainSync(()->{p.pause(true);p.releasePlayer();p.queue.clear();p.upcoming.clear();p.repeat=false;p.repeatAll=false;p.backlog.clear();p.index=0;for(int i=0;i<13;i++)p.queue.add(new Track("Test song "+i,i==2?"Needle Artist":"Test","demo","local"));p.queueChanged();p.play(0);});await(()->p.playing(),10);
  runOnMainSync(()->{for(int i=1;i<=10;i++)check(p.enqueue(p.queue.get(i),false),"Queue accepts entry "+i);check(!p.enqueue(p.queue.get(11),false),"Queue rejects eleventh upcoming song");check(p.upcoming.size()==10,"Queue stays capped");p.error="";p.moveTrack(p.queue.get(10),0);check(p.upcoming.get(0)==p.queue.get(10),"Reordering preserves current song");check(p.index==0,"Current playback identity stable");});
  check(QueueTools.filter(p.queue,"needle").equals(Arrays.asList(2)),"Artist filter retains original index");runOnMainSync(()->{ui.page=0;ui.render();ui.songSearch.setText("needle");check(ui.songCount.getText().toString().endsWith("1 of 13 songs"),"Native library search filters rows");ui.songSearch.setText("");});
  runOnMainSync(()->{int added=p.importUnique(Arrays.asList(new Track(" test   SONG 2 "," needle artist ","","query"),new Track("Brand new","Artist","new","query"),new Track("Brand new","Artist","new","query")));check(added==1,"CSV duplicate identity and intra-import duplicates skipped");p.removeTrack(p.queue.get(p.queue.size()-1));p.upcoming.clear();p.enqueue(p.queue.get(1),false);p.seek(p.duration()-3500);});await(()->p.nextPrepared,10);await(()->p.fadeOut!=null,5);int originalSession=p.audioSession();Thread.sleep(300);check(p.player.isPlaying()&&!p.nextPlayer.isPlaying(),"Only outgoing track plays during fade");await(()->p.index==1,15);check(p.playing(),"Automatic handoff plays next song");check(p.audioSession()==originalSession,"Crossfade retains DSP audio session");check(p.upcoming.isEmpty(),"Completed queue item consumed");
  runOnMainSync(()->{p.setSearchKey("test-persistence-value");check(KeyStore.load(getTargetContext()).equals("test-persistence-value"),"Encrypted key survives independent reload");p.setSearchKey("");check(KeyStore.load(getTargetContext()).isEmpty(),"Explicit key deletion works");});
  runOnMainSync(()->{ui.page=0;ui.render();ui.getWindow().addFlags(android.view.WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);});waitForIdleSync();runOnMainSync(()->{android.view.View card=((android.view.ViewGroup)((android.view.ViewGroup)ui.songRows.getChildAt(3)).getChildAt(0)).getChildAt(1);long now=SystemClock.uptimeMillis();for(int action:new int[]{0,2,1}){android.view.MotionEvent event=android.view.MotionEvent.obtain(now,now+action*20,action,action==0?30:330,20,0);card.dispatchTouchEvent(event);event.recycle();}});Thread.sleep(350);check(p.upcoming.contains(p.queue.get(3)),"Right swipe adds library track to queue");
  runOnMainSync(()->{android.view.View card=((android.view.ViewGroup)((android.view.ViewGroup)ui.songRows.getChildAt(4)).getChildAt(0)).getChildAt(1);long now=SystemClock.uptimeMillis();for(int action:new int[]{0,2,1}){android.view.MotionEvent event=android.view.MotionEvent.obtain(now,now+action*20,action,action==0?330:30,20,0);card.dispatchTouchEvent(event);event.recycle();}});waitForIdleSync();Thread.sleep(400);check(ui.deleteDialog!=null&&ui.deleteDialog.isShowing(),"Left swipe opens delete confirmation");check(p.queue.size()==13,"Swipe does not delete before confirmation");runOnMainSync(()->{check(ui.deleteDialog.getButton(android.content.DialogInterface.BUTTON_NEGATIVE)!=null,"Delete confirmation has Cancel");ui.deleteDialog.getButton(android.content.DialogInterface.BUTTON_NEGATIVE).performClick();});Thread.sleep(300);
  File dummy=new File(AudioCache.directory(getTargetContext()),"AGTEST00001.wav");try(FileOutputStream out=new FileOutputStream(dummy)){out.write(new byte[]{1,2,3});}runOnMainSync(()->{Track t=new Track("Delete fixture","Test","AGTEST00001","youtube");p.append(t);p.removeTrack(t);});check(!dummy.exists(),"Deleting song also removes cache");
  for(int page=0;page<5;page++){final int pageNumber=page;runOnMainSync(()->{ui.page=pageNumber;ui.render();});waitForIdleSync();check(ui.body.getChildCount()>0,"Page "+page+" renders");check(((android.widget.Button)ui.nav.getChildAt(4)).getLineCount()==1,"Themes navigation label stays on one line");}
  runOnMainSync(()->{p.clearLibrary();check(p.queue.isEmpty()&&p.upcoming.isEmpty(),"Clear library empties songs and queue");ui.page=0;ui.render();});check(!p.playing(),"Clear library stops playback");result.putString("result","PASS: cache cap, 10-track queue, search, deduplication, 12-second crossfade, DSP continuity, encrypted key persistence/deletion, song/cache deletion, five pages and clear list");
 }catch(Throwable e){result.putString("failure",e.toString());android.util.Log.e("AfterglowUpgrade","Failed",e);}finally{if(s!=null&&saved!=null){final PlaybackService p=s;final ArrayList<Track> library=saved,upcoming=next;final int selected=oldIndex;final boolean repeat=oldRepeat;final String originalKey=key;runOnMainSync(()->{p.pause(true);p.releasePlayer();p.queue.clear();p.queue.addAll(library);p.upcoming.clear();p.upcoming.addAll(upcoming);p.index=selected;p.repeat=repeat;p.setSearchKey(originalKey);p.save();});}if(a!=null){final MainActivity ui=a;runOnMainSync(()->{ui.page=0;ui.render();});}finish(result.containsKey("failure")?Activity.RESULT_CANCELED:Activity.RESULT_OK,result);}}
}
